const html = input.html;
const emoji = input.leagueEmoji;

const tableStart = html.indexOf('id="yw1"');
const tableEnd = html.indexOf('id="yw2"');
const tableHtml = html.substring(tableStart, tableEnd);

console.log('tableHtml length:', tableHtml.length);
console.log('tableHtml sample:', tableHtml.substring(0, 500));

const nameRegex = /<a title="([^"]+)" href="\/[^"]+\/profil\/spieler\/\d+"/g;
const valueRegex = /marktwertverlauf\/spieler\/\d+">([^<]+)<\/a>/g;
const clubRegex = /<td class="zentriert"><a title="([^"]+)" href="\/[^"]+\/startseite\/verein/g;

const names = [...tableHtml.matchAll(nameRegex)].map(m => m[1]);
const values = [...tableHtml.matchAll(valueRegex)].map(m => m[1].trim());
const clubs = [...tableHtml.matchAll(clubRegex)].map(m => m[1]);

console.log('names found:', names.length, names.slice(0, 3));
console.log('values found:', values.length, values.slice(0, 3));
console.log('clubs found:', clubs.length, clubs.slice(0, 3));

const players = [];
for (let i = 0; i < Math.min(10, names.length); i++) {
  players.push({
    name: names[i],
    club: clubs[i] || '',
    value: (values[i] || '').trim().replace('.00m', 'm')
  });
}

const leagueMatch = html.match(/Top market values ([^<]+)<\/h1>/);
const leagueName = leagueMatch ? leagueMatch[1].trim() : 'League';

console.log('leagueName:', leagueName);
console.log('players:', JSON.stringify(players.slice(0, 3)));

const lines = players
  .map((p, i) => `${i + 1}. ${p.name} (${p.club}) – ${p.value}`)
  .join('\\n');

const tweet = `${emoji} ${leagueName} – Most Valuable Players\\n\\n${lines}\\n\\nWho's the most valuable player in your league? 👇`;

return { tweet };

