module.exports = async ({ page, data }) => {
    const url = '{personal_linked_in_url_in_https_format}';  // LinkedIn profile URL

    // Go to the LinkedIn profile
    await page.goto(url, { waitUntil: 'networkidle2' });

    // Optional: Debug screenshot
    await page.screenshot({ path: '/tmp/debug_screenshot.png' });

    // Try clicking the "Connect" button directly
    let connectClicked = false;
    try {
        await page.waitForSelector('button[aria-label*="Connect"], button[aria-label="Invite"]', { visible: true, timeout: 5000 });
        await page.click('button[aria-label*="Connect"], button[aria-label="Invite"]');
        connectClicked = true;
    } catch (error) {
        console.warn(`⚠️ "Connect" button not found directly. Trying fallback through "More" button...`);
    }

    // If "Connect" button not found, try through the "More actions" menu
    if (!connectClicked) {
        try {
            await page.waitForSelector('button[aria-label="More actions"]', { visible: true, timeout: 5000 });
            await page.click('button[aria-label="More actions"]');

            await page.waitForSelector('div[role="menuitem"]:has-text("Connect")', { visible: true, timeout: 5000 });
            await page.click('div[role="menuitem"]:has-text("Connect")');
        } catch (error) {
            throw new Error(`❌ Could not find "Connect" option on the profile: ${url}`);
        }
    }

    // Confirm the connection (without message)
    try {
        await page.waitForSelector('button[aria-label="Send now"], button[aria-label="Send invitation"]', { visible: true, timeout: 5000 });
        await page.click('button[aria-label="Send now"], button[aria-label="Send invitation"]');
    } catch (error) {
        throw new Error(`❌ "Send invitation" button not found on the profile: ${url}`);
    }

    return { message: `✅ Connection request sent successfully (no message) to ${url}` };
};
