// Make sure these input parameters are mapped correctly from previous modules:
// busy: from Google Calendar (e.g., {{2.calendars}})
// startDateStr: from Google Calendar (e.g., {{2.timeMin}}) - Renamed from startDate to startDateStr for clarity
// endDateStr: from Google Calendar (e.g., {{2.timeMax}}) - Renamed from endDate to endDateStr for clarity
// senderEmail: from Webhooks (e.g., {{8.sender_email}})
// senderName: from Webhooks (e.g., {{8.sender_name}})

const busyPeriods = busy || []; // Should now be populated correctly
const initialStartDate = new Date(startDateStr);
const initialEndDate = new Date(endDateStr);
const email = senderEmail; // Using 'email' to avoid conflict with 'senderEmail' input key
let fullSenderName = senderName || '';

let firstName = 'Valued Prospect';

if (fullSenderName) {
    const nameParts = fullSenderName.split(' ');
    if (nameParts.length > 0 && nameParts[0].trim() !== '') {
        firstName = nameParts[0].trim();
    }
}

const availableSlots = [];
const meetingDurationMinutes = 15;
const daysToLookAhead = 5; // Still iterate for 5 days in calculation logic

function addMinutes(date, minutes) {
    return new Date(date.getTime() + minutes * 60000);
}

const now = new Date(); // Keep 'now' for comparison logic (past/future slots)
const isAfter5PMEDT = now.getHours() >= 17;

for (let i = 0; i < daysToLookAhead; i++) {
    let currentDate = new Date(now);
    currentDate.setDate(now.getDate() + i);
    currentDate.setHours(9, 0, 0, 0);

    if (i === 1 && isAfter5PMEDT) {
        currentDate.setHours(13, 0, 0, 0);
    } else if (i === 0 && now.getDate() === currentDate.getDate()) {
        const minStartTimeToday = addMinutes(now, 60);
        if (currentDate < minStartTimeToday) {
            currentDate = minStartTimeToday;
        }
    }

    if (currentDate > initialEndDate) { // Check against the endDate from Google Calendar input
        continue;
    }

    for (let hour = currentDate.getHours(); hour < 17; hour++) {
        for (let minute = 0; minute < 60; minute += meetingDurationMinutes) {
            const slotStart = new Date(currentDate);
            slotStart.setHours(hour, minute, 0, 0);

            const slotEnd = addMinutes(slotStart, meetingDurationMinutes);

            if (slotEnd < now) continue;
            if (slotEnd > initialEndDate) continue; // Check against the endDate from Google Calendar input

            let isBusy = false;
            for (const calendar of busyPeriods) {
                if (calendar.busy) {
                    for (const busyPeriod of calendar.busy) {
                        const busyStart = new Date(busyPeriod.start);
                        const busyEnd = new Date(busyPeriod.end);

                        if (slotStart < busyEnd && slotEnd > busyStart) {
                            isBusy = true;
                            break;
                        }
                    }
                }
                if (isBusy) break;
            }

            if (!isBusy) {
                availableSlots.push({
                    start: slotStart.toISOString(),
                    display: slotStart.toLocaleDateString('en-US', {
                        weekday: 'long',
                        month: 'long',
                        day: 'numeric',
                        year: 'numeric',
                        hour: 'numeric',
                        minute: '2-digit',
                        timeZoneName: 'short'
                    })
                });
            }
        }
    }
}

return {
    availableSlots: availableSlots,
    senderEmail: email, // Use 'email'
    senderName: firstName
};

